import unittest

class Test(unittest.TestCase):
    def test_basic(self):
        self.assertEqual(rotate_array([1,2,3,4,5,6,7], 3), [5,6,7,1,2,3,4])
    def test_k_equals_length(self):
        self.assertEqual(rotate_array([1,2,3], 3), [1,2,3])
    def test_k_larger_than_length(self):
        self.assertEqual(rotate_array([1,2,3], 4), [3,1,2])
    def test_empty(self):
        self.assertEqual(rotate_array([], 5), [])

if __name__ == '__main__':
    unittest.main()
